export const isTF=q=>q?.type==='T/F';
export function normalizeJudgment(value){const v=String(value??'').trim().toUpperCase();return ['T','TRUE','참','O','○'].includes(v)?'T':['F','FALSE','거짓','X','×'].includes(v)?'F':''}
export function normalizeTF(value){let data=value;if(typeof data==='string'){try{data=JSON.parse(data)}catch{const parts=data.split('|');if(parts.length>=3)data={judgment:parts[0],wrongPart:parts[1],correction:parts.slice(2).join('|')};else{const lines=data.split(/\r?\n/);data={judgment:lines[0].replace(/^판단\s*[:：]\s*/,''),wrongPart:lines.find(s=>/^틀린\s*부분\s*[:：]/.test(s))?.replace(/^틀린\s*부분\s*[:：]\s*/,''),correction:lines.find(s=>/^(수정|고친\s*문장)\s*[:：]/.test(s))?.replace(/^(수정|고친\s*문장)\s*[:：]\s*/,'')}}}}if(!data||typeof data!=='object')data={judgment:data};return {judgment:normalizeJudgment(data?.judgment),wrongPart:String(data?.wrongPart||'').trim(),correction:String(data?.correction||'').trim()}}
export function formatTF(value){const a=normalizeTF(value);return a.judgment==='F'?`판단: F\n틀린 부분: ${a.wrongPart}\n고친 문장: ${a.correction}`:a.judgment?'판단: T':''}
export function validateTFResponse(value){const a=normalizeTF(value);if(!a.judgment)throw new Error('T 또는 F를 선택하세요.');if(a.judgment==='F'&&(!a.wrongPart||!a.correction))throw new Error('F를 선택하면 틀린 부분과 고친 문장을 모두 입력하세요.');if(a.wrongPart.length>500||a.correction.length>2000)throw new Error('틀린 부분은 500자, 고친 문장은 2,000자 이하로 입력하세요.');return a.judgment==='T'?{judgment:'T',wrongPart:'',correction:''}:a}
const comparable=s=>String(s??'').normalize('NFKC').toLowerCase().replace(/[\s.,!?…‘’“”"'·()]/g,'');
export function gradeTF(question,value){const a=normalizeTF(value),expected=normalizeJudgment(question.answer),components={judgment:a.judgment===expected,wrongPart:null,correction:null};if(!a.judgment||a.judgment!==expected)return {correct:false,reason:'개념 부족 추정',feedback:'T/F 판단을 다시 확인하세요.',componentResults:components};if(expected==='T')return {correct:true,reason:'',feedback:'T/F 판단이 맞습니다.',componentResults:components};if(!a.wrongPart||!a.correction)return {correct:false,reason:'추가 확인 필요',feedback:'F 판단과 함께 틀린 부분·고친 문장을 모두 작성해야 합니다.',componentResults:components};components.wrongPart=comparable(a.wrongPart)===comparable(question.wrongPart)?true:null;components.correction=comparable(a.correction)===comparable(question.correction)?true:null;const correct=components.wrongPart===true&&components.correction===true;return {correct:correct?true:null,reason:correct?'':'추가 확인 필요',feedback:correct?'판단·틀린 부분·고친 문장을 모두 확인했습니다.':'F 판단은 맞습니다. 표현이 다른 부분은 채점 기준에 따라 교사가 확인합니다.',componentResults:components}}
